import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import java.time.Duration;

public class LoginTest {
    public static void main(String[] args) {
        WebDriver driver = new ChromeDriver();
        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));

        try {
            driver.get("https://opensource-demo.orangehrmlive.com/web/index.php/auth/login");

            // Invalid attempt
            WebElement username = wait.until(ExpectedConditions.visibilityOfElementLocated(By.name("username")));
            username.sendKeys("Admin");
            driver.findElement(By.name("password")).sendKeys("asmin123");
            driver.findElement(By.cssSelector("button[type='submit']")).click();

            // Correct attempt
            username = wait.until(ExpectedConditions.visibilityOfElementLocated(By.name("username")));
            username.clear();
            username.sendKeys("Admin");
            WebElement password = driver.findElement(By.name("password"));
            password.clear();
            password.sendKeys("admin123");
            driver.findElement(By.cssSelector("button[type='submit']")).click();

            // Assertion
            wait.until(ExpectedConditions.urlContains("/dashboard/index"));
            System.out.println("Login successful and redirected to dashboard.");
        } finally {
            driver.quit();
        }
    }
}
